WITH dim_totals AS (SELECT dim.level AS employee_level, e.level AS employee_level, COUNT(*) AS cnt, ROUND(SUM(e.salary), 2) AS total_salary, GROUPING_ID() AS gid FROM employees e INNER JOIN employees dim ON e.manager_id = dim.id GROUP BY GROUPING SETS ((dim.level, e.level), (dim.level))) SELECT employee_level, cnt, CASE WHEN employee_level RLIKE '^(L1|L3)$' THEN 'GROUP_B' WHEN employee_level RLIKE '^(L2|L4)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS employee_level_zone FROM dim_totals ORDER BY employee_level_zone DESC NULLS FIRST
